export interface ConnectorConfig {
  /** Brevo API key for authentication */
  brevoApiKey: string
  /** Default list ID to subscribe contacts to (can be overridden by form mapping) */
  defaultListId: number
  /** Optional mapping of Typeform field IDs to Brevo list IDs */
  fieldIdToListId?: Record<string, number>
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface BrevoContactResult {
  contactId: number
  email: string
  listIds: number[]
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function extractEmail(answers: TypeformWebhookPayload['form_response']['answers']): string | undefined {
  const emailAnswer = answers.find((a) => a.type === 'email' && a.email)
  return emailAnswer?.email
}

function extractName(answers: TypeformWebhookPayload['form_response']['answers']): { firstName: string; lastName: string } | undefined {
  // Look for short_text or text fields that could be name
  // Typeform doesn't have explicit first/last name fields in the example
  // We'll treat the first text field as first name
  const nameAnswer = answers.find((a) => a.type === 'text' && a.text)
  if (!nameAnswer) return undefined

  const fullName = nameAnswer.text.trim()
  const parts = fullName.split(/\s+/)
  return {
    firstName: parts[0] ?? '',
    lastName: parts.slice(1).join(' ') || ''
  }
}

function determineListIds(
  answers: TypeformWebhookPayload['form_response']['answers'],
  config: ConnectorConfig
): number[] {
  const listIds = new Set<number>()

  // Always include default list
  listIds.add(config.defaultListId)

  // Check for field ID mappings
  if (config.fieldIdToListId) {
    for (const answer of answers) {
      const mappedListId = config.fieldIdToListId[answer.field.id]
      if (mappedListId) listIds.add(mappedListId)
    }
  }

  return Array.from(listIds)
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig
): Promise<BrevoContactResult> {
  // Validate required config
  if (!config.brevoApiKey) {
    throw new Error('Missing required config: brevoApiKey')
  }
  if (!config.defaultListId || typeof config.defaultListId !== 'number') {
    throw new Error('Missing required config: defaultListId (must be a number)')
  }

  // Validate payload structure
  if (!payload.form_response?.answers?.length) {
    throw new Error('Invalid payload: missing form_response.answers')
  }

  const email = extractEmail(payload.form_response.answers)
  if (!email) {
    throw new Error('Required field missing: email not found in form answers')
  }

  const name = extractName(payload.form_response.answers)
  const listIds = determineListIds(payload.form_response.answers, config)

  // Build Brevo request body
  const body = {
    email,
    attributes: {
      FNAME: name?.firstName ?? '',
      LNAME: name?.lastName ?? ''
    },
    listIds
  }

  const fetchFn = getFetch(config)
  const response = await fetchFn('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': config.brevoApiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(
      `Brevo API error: ${response.status} ${response.statusText} ` +
      `at POST https://api.brevo.com/v3/contacts - ${errorText}`
    )
  }

  const result = (await response.json()) as { id: number }

  return {
    contactId: result.id,
    email,
    listIds
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      brevoApiKey: 'test-api-key',
      defaultListId: 123,
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.contactId).toBe(12345)
    expect(result.email).toBe('laura@example.com')
    expect(result.listIds).toEqual([123])
  })
})

describe('handle', () => {
  let calls: RecordedCall[]
  let fetch: typeof fetch
  let baseConfig: ConnectorConfig

  beforeEach(() => {
    const fake = fakeFetch((req) => {
      if (req.url === 'https://api.brevo.com/v3/contacts' && req.method === 'POST') {
        return jsonResponse({ id: 999 }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetch = fake.fetch
    calls = fake.calls
    baseConfig = {
      brevoApiKey: 'test-key-123',
      defaultListId: 42,
      fetch
    }
  })

  it('happy path: creates contact with email, name, and default list', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-1',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-1',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'john@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'John Doe', field: { id: 'f2', type: 'short_text' } }
        ]
      }
    }

    const result = await handle(payload, baseConfig)

    expect(result).toEqual({
      contactId: 999,
      email: 'john@example.com',
      listIds: [42]
    })

    expect(calls).toHaveLength(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.brevo.com/v3/contacts')
    expect(call.headers.get('api-key')).toBe('test-key-123')
    expect(call.json).toEqual({
      email: 'john@example.com',
      attributes: { FNAME: 'John', LNAME: 'Doe' },
      listIds: [42]
    })
  })

  it('uses fieldIdToListId mapping to add additional list IDs', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-2',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-2',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'jane@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'Jane Smith', field: { id: 'f2', type: 'short_text' } },
          { type: 'multiple_choice', text: 'Option A', field: { id: 'list-field-1', type: 'multiple_choice' } }
        ]
      }
    }

    const config: ConnectorConfig = {
      ...baseConfig,
      fieldIdToListId: { 'list-field-1': 99 }
    }

    const result = await handle(payload, config)

    expect(result.listIds).toEqual([42, 99])
    expect(calls[0].json).toEqual({
      email: 'jane@example.com',
      attributes: { FNAME: 'Jane', LNAME: 'Smith' },
      listIds: [42, 99]
    })
  })

  it('handles missing last name (single word name)', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-3',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-3',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'cher@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'Cher', field: { id: 'f2', type: 'short_text' } }
        ]
      }
    }

    const result = await handle(payload, baseConfig)

    expect(result.email).toBe('cher@example.com')
    expect(calls[0].json).toEqual({
      email: 'cher@example.com',
      attributes: { FNAME: 'Cher', LNAME: '' },
      listIds: [42]
    })
  })

