    const payload: TypeformWebhookPayload = {
      event_id: 'evt-4',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-4',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'text', text: 'No Email', field: { id: 'f2', type: 'short_text' } }
        ]
      }
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Required field missing: email not found in form answers')
  })

  it('throws when form_response.answers is missing', async () => {
    const payload = {
      event_id: 'evt-5',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-5',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: []
      }
    } as unknown as TypeformWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Invalid payload: missing form_response.answers')
  })

