    const payload: TypeformWebhookPayload = {
      event_id: 'evt-6',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-6',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'f1', type: 'email' } }
        ]
      }
    }

    const config: ConnectorConfig = { ...baseConfig, brevoApiKey: '' }

    await expect(handle(payload, config)).rejects.toThrow('Missing required config: brevoApiKey')
  })

  it('throws when defaultListId is missing from config', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-7',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-7',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'f1', type: 'email' } }
        ]
      }
    }

    const config: ConnectorConfig = { ...baseConfig, defaultListId: 0 as unknown as number }

    await expect(handle(payload, config)).rejects.toThrow('Missing required config: defaultListId')
  })

  it('throws on non-2xx response from Brevo API', async () => {
    const errorFetch = fakeFetch(() => jsonResponse({ error: 'contact exists' }, 400))

    const payload: TypeformWebhookPayload = {
      event_id: 'evt-8',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-8',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'exists@example.com', field: { id: 'f1', type: 'email' } }
        ]
      }
    }

    await expect(handle(payload, { ...baseConfig, fetch: errorFetch.fetch })).rejects.toThrow(
      'Brevo API error: 400 Bad Request at POST https://api.brevo.com/v3/contacts'
    )
  })

  it('includes response body in error message on failure', async () => {
    const errorFetch = fakeFetch(() => jsonResponse({ code: 'DUPLICATE', message: 'Contact already exists' }, 400))

    const payload: TypeformWebhookPayload = {
      event_id: 'evt-9',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-9',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'dup@example.com', field: { id: 'f1', type: 'email' } }
        ]
      }
    }

    try {
      await handle(payload, { ...baseConfig, fetch: errorFetch.fetch })
    } catch (e) {
      expect(String(e)).toContain('Contact already exists')
    }
  })

  it('deduplicates listIds when mapping produces duplicates', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-10',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-10',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'dedupe@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'Test User', field: { id: 'f2', type: 'short_text' } },
          { type: 'multiple_choice', text: 'Option', field: { id: 'same-list', type: 'multiple_choice' } },
          { type: 'multiple_choice', text: 'Option', field: { id: 'same-list', type: 'multiple_choice' } }
        ]
      }
    }

    const config: ConnectorConfig = {
      ...baseConfig,
      fieldIdToListId: { 'same-list': 42 } // Same as defaultListId
    }

    const result = await handle(payload, config)
    expect(result.listIds).toEqual([42])
  })
})

